const collections = new Map();
/**
 * Register one or more iconify collections so the shared {@link Icon}
 * component can resolve `set:name` references at render time. Call from the
 * consuming site's entrypoint with the collections it wants available.
 *
 * @example
 * ```ts
 * import solar from "@iconify-json/solar/icons.json";
 * import { registerIconCollections } from "@semio-community/ecosystem-site-core";
 * registerIconCollections({ solar });
 * ```
 */
export function registerIconCollections(entries) {
    for (const [name, data] of Object.entries(entries)) {
        collections.set(name, data);
    }
}
export function getIconCollection(name) {
    return collections.get(name);
}
